std::string numrepr(double x){std::ostringstream o;o<<std::setprecision(17)<<x;return o.str();}
const char* opname(int ver,std::uint32_t op){if(ver==51&&op<std::size(kLuaOps_5_1_5))return kLuaOps_5_1_5[op];if(ver==52&&op<std::size(kLuaOps_5_2_4))return kLuaOps_5_2_4[op];if(ver==53&&op<std::size(kLuaOps_5_3_6))return kLuaOps_5_3_6[op];if(ver==54&&op<std::size(kLuaOps_5_4_8))return kLuaOps_5_4_8[op];if(ver==55&&op<std::size(kLuaOps_5_5_0))return kLuaOps_5_5_0[op];return nullptr;}
bool read_code(Reader&r,LuaProto&p){auto no=r.count();if(!no)return false;auto n=*no;if(n>2000000)return r.fail("instruction count too large");if(r.ver==55&&!r.align(r.out->instruction_size))return false;if(n*r.out->instruction_size>r.d.size()-r.p)return r.fail("instruction vector out of range");p.instructions.reserve(std::size_t(n));for(std::uint64_t i=0;i<n;++i){auto raw=static_cast<std::uint32_t>(r.rawu(r.out->instruction_size));LuaInstruction x;x.pc=static_cast<std::uint32_t>(i);x.raw=raw;if(r.out->instruction_size==4){if(r.ver<=53){x.opcode=raw&0x3f;x.a=(raw>>6)&0xff;x.c=(raw>>14)&0x1ff;x.b=(raw>>23)&0x1ff;x.bx=(raw>>14)&0x3ffff;}else{x.opcode=raw&0x7f;x.a=(raw>>7)&0xff;x.b=(raw>>16)&0xff;x.c=(raw>>24)&0xff;x.bx=(raw>>15)&0x1ffff;}if(auto n=opname(r.ver,x.opcode))x.name=n;else{x.name="OP_"+std::to_string(x.opcode);r.out->modified_header=true;}}p.instructions.push_back(std::move(x));}return r.out->error.empty();}
bool read_constants(Reader&r,LuaProto&p){auto no=r.count();if(!no)return false;auto n=*no;if(n>1000000)return r.fail("constant count too large");p.constants.reserve(std::size_t(n));for(std::uint64_t i=0;i<n;++i){auto t=r.b();if(!r.out->error.empty())return false;switch(t){case 0:p.constants.push_back("nil");break;case 1:if(r.ver<=53){auto bv=r.b();p.constants.push_back(bv?"true":"false");}else p.constants.push_back("false");break;case 17:p.constants.push_back("true");break;case 3:{if(r.ver>=54){std::int64_t v;if(r.ver==55){auto x=r.var55();if(!x)return false;auto u=*x;v=(u&1)?static_cast<std::int64_t>(~(u>>1)):static_cast<std::int64_t>(u>>1);}else v=r.raws(r.out->integer_size);p.constants.push_back("int:"+std::to_string(v));}else p.constants.push_back("float:"+numrepr(r.number(r.out->number_size)));break;}case 19:{if(r.ver>=54)p.constants.push_back("float:"+numrepr(r.number(r.out->number_size)));else{auto v=r.raws(r.out->integer_size);p.constants.push_back("int:"+std::to_string(v));}break;}case 4:case 20:{auto s=r.str();if(!s)return false;p.constants.push_back("str:"+*s);break;}default:return r.fail("unknown/modified constant tag "+std::to_string(t));}}return true;}
