std::string disasm(const LuaInfo&i){std::ostringstream o;o<<"Lua "<<i.version<<" bytecode\n";for(const auto&p:i.protos){o<<"\nProto "<<p.path<<" source="<<p.source<<" lines="<<p.line_defined<<"-"<<p.last_line_defined<<" params="<<unsigned(p.num_params)<<" stack="<<unsigned(p.max_stack)<<"\n";if(!p.constants.empty()){o<<"Constants:\n";for(std::size_t n=0;n<p.constants.size();++n)o<<"  K"<<n<<" = "<<p.constants[n]<<"\n";}o<<"Instructions:\n";for(const auto&x:p.instructions)o<<"  "<<std::setw(5)<<x.pc<<"  0x"<<std::hex<<std::setw(8)<<std::setfill('0')<<x.raw<<std::setfill(' ')<<std::dec<<"  "<<x.name<<" A="<<x.a<<" B="<<x.b<<" C="<<x.c<<" Bx="<<x.bx<<"\n";}return o.str();}
