LuaInfo parse_luac(std::span<const std::uint8_t>d){LuaInfo o;Reader r{d,0,&o,0,true,{}};if(!parse_header(r))return o;if(r.ver>=53)r.b();if(!read_proto(r,"0",std::nullopt,0))return o;o.parsed_bytes=r.p;o.valid=o.error.empty()&&!o.protos.empty();if(r.p<d.size())o.modified_header=true;return o;}
Finding lua_finding(const LuaInfo&i){Finding f;f.kind="bytecode";f.family="Lua bytecode";if(!i.valid){f.state="FAILED";if(!i.error.empty()){std::ostringstream eo;eo<<i.error<<" at 0x"<<std::hex<<i.error_offset;f.negative_evidence.push_back(eo.str());}return f;}f.state="CONFIRMED";f.variant=i.version;f.evidence={"Lua chunk header/number format validated","prototype tree and constants/instructions structurally parsed"};f.fields["prototypes"]=std::to_string(i.protos.size());std::size_t ins=0,ks=0;for(const auto&p:i.protos){ins+=p.instructions.size();ks+=p.constants.size();}f.fields["instructions"]=std::to_string(ins);f.fields["constants"]=std::to_string(ks);if(i.modified_header)f.negative_evidence.push_back("trailing bytes or nonstandard opcode evidence present");return f;}
LuaExtractResult extract_lua_disasm(const LuaInfo&i,const std::filesystem::path&out){LuaExtractResult r;if(!i.valid){r.error="Lua chunk not valid";return r;}std::ofstream f(out,std::ios::binary);if(!f){r.error="cannot create Lua disassembly";return r;}auto s=disasm(i);f.write(s.data(),static_cast<std::streamsize>(s.size()));r.success=bool(f);r.disasm_path=out;if(!r.success)r.error="write failed";return r;}
